UPDATE document_definition_versions
SET schema_json = '{"code":"QUEBEC_DRIVER_LICENSE","country":"CA","documentType":"DRIVING_LICENSE","version":"2024","side":"FRONT","mrzFormat":"NONE","issuingJurisdiction":"QC","reading":"Quebec driver license front. The title is Permis de conduire, the Quebec wordmark is at the upper left, the photo is on the left, and a fleur-de-lis is on the right. The large number under the title is documentNumber. The surname is the line directly under that number. The given names are the next line. The date labeled Date de naissance (A-M-J) is dateOfBirth. On the bottom line, read left to right: the date after Valide le is dateOfIssue, the date after Expire le is expirationDate. These two dates are different. expirationDate is never the Valide le date. The footer about the yearly payment on the birthday is not a date field.","fields":[{"name":"firstName","type":"NAME","required":true,"normalizer":"ICAO_NAME","hint":"given names on the line under the surname"},{"name":"lastName","type":"NAME","required":true,"normalizer":"ICAO_NAME","hint":"surname on the line directly under the document number; it may contain two words"},{"name":"dateOfBirth","type":"DATE","required":true,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd","yyyy/MM/dd","dd/MM/yyyy","MM/dd/yyyy"],"hint":"date labeled Date de naissance (A-M-J); write yyyy-MM-dd"},{"name":"documentNumber","type":"DOCUMENT_NUMBER","required":true,"hint":"large number under the title Permis de conduire"},{"name":"dateOfIssue","type":"DATE","required":true,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd","yyyy/MM/dd","dd/MM/yyyy","MM/dd/yyyy"],"hint":"left date on the bottom line, the date after Valide le"},{"name":"expirationDate","type":"DATE","required":true,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd","yyyy/MM/dd","dd/MM/yyyy","MM/dd/yyyy"],"hint":"right date on the bottom line, the date after Expire le"},{"name":"sex","type":"SEX","required":false,"hint":"labeled Sexe"},{"name":"address","type":"ADDRESS","required":false,"hint":"address lines under the date of birth, including the city and postal code"},{"name":"licenseClass","type":"STRING","required":false,"hint":"labeled Classe(s)"},{"name":"conditions","type":"STRING","required":false,"hint":"labeled Cond."},{"name":"mentions","type":"STRING","required":false,"hint":"labeled Mention(s)"},{"name":"referenceNumber","type":"STRING","required":false,"hint":"labeled No de reference"},{"name":"heightCm","type":"STRING","required":false,"hint":"labeled Taille (cm), digits only"},{"name":"eyeColor","type":"STRING","required":false,"hint":"labeled Yeux"}],"rules":[{"level":"L3","code":"DOB_AFTER_ISSUE","expression":"dateOfBirth > dateOfIssue","severity":"ERROR"}]}'
WHERE id = '018f5a00-0000-7000-8000-0000000000a2';

UPDATE document_definition_versions
SET schema_json = '{"code":"QUEBEC_DRIVER_LICENSE","country":"CA","documentType":"DRIVING_LICENSE","version":"2024","side":"BACK","mrzFormat":"NONE","issuingJurisdiction":"QC","reading":"Quebec driver license back, issued by the SAAQ. No photo, no holder name, and no MRZ. A PDF417 barcode is at the upper left and a linear barcode is at the upper right. The sentence after CLASSE(S): is classDescription. The edition in parentheses at the lower right, such as (2024-01), is cardEdition. The card prints Quebec, saaq.gouv.qc.ca, and Renseignements 1 800 361-7620. Choose code QUEBEC_DRIVER_LICENSE and side BACK.","fields":[{"name":"barcode","type":"STRING","required":true,"hint":"PDF417 barcode at the upper left; value PRESENT when that barcode is visible. The linear barcode at the upper right is not this field"},{"name":"classDescription","type":"STRING","required":false,"hint":"sentence printed after CLASSE(S):"},{"name":"cardEdition","type":"STRING","required":false,"hint":"edition in parentheses at the lower right, next to saaq.gouv.qc.ca, such as 2024-01"}],"rules":[]}'
WHERE id = '018f5a00-0000-7000-8000-0000000000c2';
